from sales_dashboard.loader import daily_conversion_counts
from sales_dashboard.metrics import pooled_conversion_rate, conversions_in_window


def campaign_summary(groups, days):
    """Summarize pooled conversion and recent conversions for campaign groups."""
    all_events = [event for events in groups.values() for event in events]
    if all_events:
        first_day = min(event["day"] for event in all_events)
        last_day = max(event["day"] for event in all_events)
        daily_counts = daily_conversion_counts(all_events, first_day, last_day)
        recent = conversions_in_window(daily_counts, days)
    else:
        recent = 0

    return {
        "rate": round(pooled_conversion_rate(groups), 3),
        "recent": recent,
        "groups": sum(bool(events) for events in groups.values()),
    }


def top_converting_groups(groups, n):
    """Return the ``n`` nonempty groups ranked by conversion rate."""
    ranked = [name for name, events in groups.items() if events]
    ranked.sort(key=lambda name: (-conversion_rate_for_group(groups[name]), name))
    return ranked[:n]


def conversion_rate_for_group(events):
    """Return the conversion rate for a nonempty group."""
    from sales_dashboard.metrics import conversion_rate

    return conversion_rate(events)
